        add(
          "unequip",
          `Unequip ${items[item.id].name}`,
          { item: uid, slot },
          { unequip: true },
        );
    }
    for (const item of s.inventory) {
      const d = items[item.id];
      if (d.slot === "gem") continue;
      for (const slot of Object.keys(s.equipment).filter((k) =>
        k.startsWith(d.slot),
      )) {
