        if (c.quest) s.quest = true;
        if (c.clean || c.cleanHex)
          s.deck = s.deck.filter((x) => cards[x.id].type !== "Hex");
        if (c.clean)
          for (const x of [...s.inventory])
            if (items[x.id].cursed) this.removeItem(x.uid);
        if (s.hp <= 0)
          this.finish(false, events.find((e) => e.id === s.event).name);
        else if (c.fight)
          this.beginBattle([{ uid: this.uid(), enemy: c.fight, restless: 0 }]);
        else this.resolveTile();
        break;
      }
      case "rewardCard":
        this.addCard(a.id);
        s.reward.cards = null;
        break;
      case "skipReward":
        s.reward.cards = null;
        break;
      case "rewardGem":
        this.addItem(a.id);
        s.reward.gem = false;
        break;
      case "rewardSetting":
        this.addItem(a.id);
        s.reward.setting = false;
        break;
      case "continueReward":
        if (s.reward.boss) this.finish(true);
        else this.resolveTile();
        break;
      case "leave":
        this.resolveTile();
        break;
      case "heal":
        this.spend(20);
        s.hp = Math.min(s.maxHp, s.hp + 20);
        s.shop.healUsed = true;
        break;
      case "gossip":
        this.spend(15);
        s.revealedArchon = s.archon;
        s.shop.gossipUsed = true;
        s.nextTavernHealer = this.rand() < 0.75;
        s.nextHealerHint = s.nextTavernHealer;
        this.log(
          s.nextHealerHint
            ? "A healer will visit the next Tavern."
            : "No healer will visit the next Tavern.",
        );
        this.log("The traveler names " + enemies[s.archon].name + ".");
        break;
      case "buy": {
        const id = s.shop.stock.splice(a.index, 1)[0];
        this.spend(a.price);
        s.stats.purchases.push(id);
        if (id.startsWith("card:")) this.addCard(id.slice(5));
        else this.addItem(id);
        break;
      }
      case "sell": {
        const item = this.getItem(a.uid);
        if (items[item.id].cursed) this.spend(a.value);
        else this.gainGold(a.value);
        s.stats.sales.push(item.id);
        this.removeItem(a.uid);
        break;
      }
      case "socket":
        this.getItem(a.uid).gem = a.gem;
        break;
      case "unsocket":
        this.getItem(a.uid).gem = null;
        break;
      case "remove":
        this.spend(40);
        s.shop.removeUsed = true;
        s.deck = s.deck.filter((x) => x.uid !== a.uid);
        break;
      case "removeHex":
        if (a.costs.gold) this.spend(a.costs.gold);
        if (a.costs.hp) {
          s.hp -= a.costs.hp;
          s.stats.damageTaken += a.costs.hp;
        }
        s.deck = s.deck.filter(
          (x) => x.uid !== a.uid && x.uid !== a.sacrificeCard,
        );
        if (a.sacrificeItem) this.removeItem(a.sacrificeItem);
        this.log(a.label);
        break;
      case "upgrade": {
        const c = s.deck.find((x) => x.uid === a.uid),
          u = cards[c.id].upgrade;
        if (u.gold) this.spend(u.gold);
        if (u.hp) {
          s.hp -= u.hp;
          s.stats.damageTaken += u.hp;
        }
        if (a.sacrifice) s.deck = s.deck.filter((x) => x.uid !== a.sacrifice);
        c.upgrade = true;
        break;
      }
      case "place": {
        const c = b.hand.find((x) => x.uid === a.uid),
          d = cards[c.id];
        b.hand = b.hand.filter((x) => x.uid !== a.uid);
        b.focus -= a.costs.focus;
        b.milky = false;
        const slot = b.grid[a.slot];
        if (d.stack === "recall" && slot.length) {
          for (let i = slot.length - 1; i >= 0; i--)
            if (cards[slot[i].id].recall != null && !slot[i].lock)
              b.discard.push(
                ...slot
                  .splice(i, 1)
                  .map((x) => ({ uid: x.uid, id: x.id, upgrade: x.upgrade })),
              );
        }
        const inst = this.instance(c);
        slot.push(inst);
        if (
          d.bondHP &&
          this.neighbors(a.slot).some((j) => top(b.grid[j]).element === "Earth")
        )
          inst.hp += d.bondHP;
        inst.maxHp = Math.max(inst.maxHp, inst.hp);
        if (d.onPlaceCharge)
          inst.charge += this.neighbors(a.slot).filter(
            (j) => top(b.grid[j]).element === "Fire",
          ).length;
        if (d.onPlaceFocus) b.focus += d.onPlaceFocus;
        break;
      }
      case "recall":
        b.focus -= a.costs.focus;
        b.discard.push(
          ...b.grid[a.slot].map((c) => ({
            uid: c.uid,
            id: c.id,
            upgrade: c.upgrade,
          })),
        );
        b.grid[a.slot] = [];
        break;
      case "activatePhase":
        b.discard.push(...b.hand);
        b.hand = [];
        b.phase = "activate";
        break;
      case "activate":
        this.activate(a);
        break;
      case "endTurn":
        this.endTurn();
        break;
      case "ward": {
        const c = b.grid[a.slot].find((c) => c.uid === a.uid),
          h = b.reaction;
        const loss = Math.min(c.ward, h.damage);
        c.ward -= loss;
        h.damage -= loss;
        h.weaknessBonus = 0;
        h.weaknessElement = null;
        if (!c.ward) c.zeroWard = true;
        this.presentIncomingNode(
          "defend",
          { slot: a.slot, amount: loss, loss, name: "Ward absorbs" },
          { kind: "card", slot: a.slot },
        );
        this.advanceHit();
        this.pump();
        break;
      }
      case "block":
      case "bracelet": {
        const p = (a.type === "block" ? b.shields : b.bracelets).find(
          (x) => x.uid === a.uid,
        );
        b.reaction.weaknessBonus = 0;
        b.reaction.weaknessElement = null;
        const r = blockHit(
          p.block,
          p.element,
          b.reaction.damage,
          b.reaction.element,
        );
        const stopped = b.reaction.damage - r.remaining;
        const loss = p.block - r.block;
        p.block = r.block;
        b.reaction.damage = r.remaining;
        this.presentIncomingNode(
          "defend",
          {
            slot: a.type === "block" ? p.slot : null,
            item: a.type === "bracelet" ? a.uid : null,
            amount: stopped,
            loss,
            name: "Blocked",
          },
          a.type === "block"
            ? { kind: "card", slot: p.slot }
            : { kind: "item", uid: a.uid },
        );
        this.advanceHit();
        this.pump();
        break;
      }
      case "intercept":
        this.intercept(a.slot);
        this.pump();
        break;
      case "skipEquipment":
        this.log("You let the hit through without using remaining defenses.");
        b.reaction.stage = "player";
        this.advanceHit();
        this.pump();
        break;
      case "takeHit":
        b.reaction.column = -1;
        b.reaction.stage = "bracelet";
        this.advanceHit();
        this.pump();
        break;
    }
    tutorialAfter(this, a);
    return this.observe();
  }
  removeItem(uid) {
    const s = this.s;
    for (const k of Object.keys(s.equipment))
      if (s.equipment[k] === uid) s.equipment[k] = null;
    for (const x of s.inventory) if (x.gem === uid) x.gem = null;
    s.inventory = s.inventory.filter((x) => x.uid !== uid);
  }
  observe() {
    const s = this.s;
    const o = {
      version: VERSION,
      tutorial: s.tutorial
        ? {
            id: s.tutorial.id,
            version: s.tutorial.version,
            name: s.tutorial.name,
            completed: s.tutorial.completed,
            fight: s.tutorial.fight,
            step: s.tutorial.step,
            lesson: s.tutorial.lesson,
            guide: tutorialGuide(this),
          }
        : null,
      mode: s.mode,
      classId: s.classId,
      hp: Math.max(0, s.hp),
      maxHp: s.maxHp,
      gold: s.gold,
      deck: clone(s.deck),
      inventory: clone(s.inventory),
      equipment: clone(s.equipment),
      bonuses: this.bonuses(),
      status: clone(s.status),
      field: clone(s.field),
      log: s.log.slice(-30),
      steps: s.steps,
      stats: clone(s.stats),
      startGem: s.startGem,
      archon: s.revealedArchon ? enemies[s.revealedArchon].name : null,
      pendingArmor: s.pendingArmor,
      nextHealerHint: s.nextHealerHint,
    };
    if (s.mode === "battle") {
      o.battle = clone(s.battle);
      delete o.battle.jobs;
      o.battle.telegraphs = this.gridTelegraphs();
      o.battle.deck.sort((a, b) => a.id.localeCompare(b.id) || a.uid - b.uid);
      o.battle.enemies = o.battle.enemies
        .filter((e) => e.hp > 0 || (enemies[e.id].onDeath && !e.deathResolved))
        .map((e) => ({
          ...e,
          hp: Math.max(0, e.hp),
          statusImmunity: enemyStatusImmunity(e),
          signature:
            enemies[e.id].signature +
            (enemyStatusImmunity(e)
              ? ` Immune to ${statusName(enemyStatusImmunity(e))} while ${e.element}.`
              : ""),
          counter: enemies[e.id].counter,
          rotation: enemies[e.id].rotation.map((t) => ({
            ...clone(t),
            ...(t.currentElement ? { element: e.element } : {}),
          })),
          onDeath: clone(enemies[e.id].onDeath),
          tell: e.hp <= 0 ? clone(enemies[e.id].onDeath) : this.tell(e),
        }));
    }
    if (s.mode === "event") o.event = events.find((e) => e.id === s.event);
    if (s.mode === "tavern") o.shop = clone(s.shop);
    if (s.mode === "item") o.itemOffer = clone(s.itemOffer);
    if (s.mode === "reward") o.reward = clone(s.reward);
    if (s.mode === "result") {
      o.outcome = s.outcome;
      o.cause = s.cause;
      o.death = clone(s.death);
      o.seed = s.seed;
      o.history = clone(s.history);
    }
    return o;
  }
  save() {
    return clone(
      this.s.mode === "battle" && this.s.checkpoint && !this.s.tutorial
        ? this.s.checkpoint
        : this.s,
    );
  }
}

sources.tutorial.mjs:
import { cards, items, enemies } from "./content.mjs";
export const TUTORIAL = {
  id: "stratum1",
  version: 2,
  name: "The First Clearing",
  seed: 11001,
};
const steps = [];
const note = (id, title, text, focus = "", setup = null) =>
  steps.push({ id, title, text, focus, setup, kind: "note" });
const action = (
  id,
  title,
  text,
  match,
  focus = "",
  gesture = null,
  setup = null,
) =>
  steps.push({ id, title, text, match, focus, gesture, setup, kind: "action" });
const ui = (id, title, text, control, focus) =>
  steps.push({ id, title, text, control, focus, kind: "ui" });
const place = (id, card, slot, text, gesture = null) =>
  action(
    id,
    "Placement · " + cards[card].name,
    text,
    { type: "place", card, slot },
    "",
    gesture,
  );
const activate = (id, slot, text, element) =>
  action(id, "Activation", text, {
    type: "activate",
    slot,
    ...(element ? { element } : {}),
  });
const phase = (id) =>
  action(
    id,
    "Advance to Activation",
    "Your placement is finished. Press the arrow from Placement to Activation. Focus returns next round; this phase uses Channel.",
    { type: "activatePhase" },
  );
const end = (
  id,
  text = "Press the arrow to Enemy. Watch the Tell resolve before making your defense choice.",
) => action(id, "Let the enemy act", text, { type: "endTurn" });
const defend = (id, type, slot, text) =>
  action(id, "Choose your defense", text, {
    type,
    ...(slot == null ? {} : { slot }),
  });
const move = (id, x, y, text) =>
  action(id, "Follow the path", text, { type: "move", x, y });
const reward = (id, card, text) =>
  action(id, "Choose your reward", text, { type: "rewardCard", id: card });
const back = (id) =>
  action(
    id,
    "Back to the Clearing",
    "Return to the overworld. Your cards recover their allowances between battles.",
    { type: "continueReward" },
  );
note(
  "welcome",
  "The First Clearing",
  "A quiet grove to learn the journey. Each lesson waits for you. Read the glowing callout, then click Continue. You can pause or return to Start at any time.",
  ".field",
  "gold",
);
note(
  "gold",
  "A glint among the leaves",
  "Gold has appeared to your right. The eight arrow buttons move one space in the direction they point. Diagonal moves cost one space too.",
  ".direction-pad",
);
move("gold-move", 6, 5, "Click the glowing east arrow to move onto the Gold.");
note(
  "gold-gained",
  "Gold collected",
  "Your Gold increased by 200. These coins will pay for the Tavern lessons later. Ordinary journeys offer smaller, variable caches.",
  "header .gold",
  "ring",
);
move("item-move", 7, 5, "An item has appeared one space east. Move to it.");
action(
  "ring-take",
  "An item is yours to inspect",
  "Take the Rootbound Ring. In ordinary journeys you may leave an item behind.",
  { type: "takeItem", index: 0 },
);
ui(
  "inventory-open",
  "Your belongings",
  "Click Inventory. Items you wear appear in Equipped; everything else stays in the Satchel.",
  "inventory",
  '[data-ui="inventory"]',
);
action(
  "ring-equip",
  "Equip the Ring",
  "Drag the Rootbound Ring from the Satchel to your right finger. You may also inspect it and choose Equip. It adds a separate 2-damage hit to your first attack each turn.",
  { type: "equip", itemId: "ring", slot: "finger2" },
  '.satchel, [data-equip-slot="finger2"]',
);
note(
  "gear-ready",
  "Ready for the road",
  "The Ring is now Equipped, not in the Satchel. During player movement you can equip and unequip items. Gems are different: socket them only at a Tavern.",
  '[data-equip-slot="finger2"]',
  "mote",
);
move(
  "mote-move",
  8,
  5,
  "A Mosswing waits to the east. The arrow moves directly onto it. Clicking the enemy itself normally opens its details.",
);
note(
  "reveal",
  "Insight reveals your choices",
  "Watch the four cards dealt from your Grimoire. Insight starts at 4 and falls to 0 as Reveal finishes. It controls how many cards you see, not how many you may place.",
  ".resources > span:nth-child(1), .hand",
);
ui(
  "grimoire-open",
  "Your Grimoire",
  "Open the Grimoire to see your deck. Undrawn cards remain there; discarded cards recycle when it empties.",
  "grimoire",
  '[data-ui="grimoire"]',
);
note(
  "focus",
  "Focus places cards",
  "Focus starts at 1. This Shield costs 1 Focus to place. Drag it from your revealed hand to the outlined space; the card stays there between rounds.",
  ".resources > span:nth-child(2), .hand",
);
place(
  "shield-place",
  "shield",
  18,
  "Drag a Shield onto the outlined space. Keyboard: focus the Shield, press Enter, close its details, then Enter on the marked space.",
  "drag-place",
);
note(
  "focus-empty",
  "Focus is spent",
  "Focus is now 0, so no more cost-1 cards can be placed. Do not worry: it returns to 1 next round. The phase arrows move only forward.",
  ".resources > span:nth-child(2)",
);
phase("first-phase");
note(
  "tell3",
  "Read the Tell",
  "Mosswing is about to deal 3 Arcane damage. A Shield activation costs 1 Channel and creates 4 block for this turn. Channel starts at 2.",
  ".enemy .tell, .resources > span:nth-child(3)",
);
activate(
  "shield-activate",
  18,
  "Click Activate on your Shield to prepare 4 block.",
);
end("first-enemy");
defend(
  "shield-block3",
  "block",
  18,
  "Click your glowing Shield to absorb the 3-damage attack.",
);
note(
  "shield-expiry",
  "The card stays; its block expires",
  "The attack was blocked. Unused Shield block disappears at round end, but the card remains. Activate it again to make fresh block. This Shield has one use left; keep an eye on Channel and each card’s allowance.",
  '[data-slot="18"], .resources',
);
place(
  "blast-place",
  "blast",
  22,
  "Place a Blast on the outlined space. Your refreshed Focus pays for it.",
);
phase("second-phase");
activate(
  "second-shield",
  18,
  "Prepare the Shield again. The next enemy attack deals 5, so its 4 block will need help from your Bracelet.",
);
activate(
  "first-blast",
  22,
  "Attack by dragging Blast onto Mosswing, or double-click its Activate button to hit the top enemy. Blast deals 4; your Ring adds a separate 2.",
);
end("second-enemy");
defend(
  "shield-block5",
  "block",
  18,
  "Click Shield: it stops 4 of the 5 damage. The remaining attack continues toward you.",
);
defend(
  "bracelet-block1",
  "bracelet",
  null,
  "Click your right Bracelet. It blocks the last 1 damage without spending Channel. Its 2 block refills each enemy round.",
);
place(
  "synergy-place",
  "blast",
  23,
  "Place a second Blast immediately beside the first, on the outlined space.",
);
note(
  "synergy",
  "Neighbors can change a card",
  "The connecting line shows a real interaction. Each adjacent Blast adds +1 damage, so each now shows 5. Inspect card details to learn which neighbors, patterns and stacks matter.",
  '[data-slot="22"], [data-slot="23"]',
);
phase("third-phase");
activate(
  "synergy-kill",
  23,
  "Activate the new Blast against Mosswing. Its 5 damage and the Ring’s first-hit 2 will finish this fight.",
);
reward(
  "ward-reward",
  "ward",
  "Choose Ward. This reward goes into your Grimoire, and we will use it in the next fight.",
);
back("first-back");
note(
  "pursuit",
  "An item beyond your reach",
  "An item lies northeast, but a Rootling is approaching. Move toward the item, then watch the enemy follow one space at a time and stop on your space.",
  ".field, .direction-pad",
  "pursuit",
);
move(
  "pursuit-move",
  9,
  4,
  "Take the northeast step toward the distant item. This uses your last movement; the Rootling then gets its turn.",
);
note(
  "caught",
  "Enemies move too",
  "The Rootling moved onto your space and started a battle. On ordinary maps, inspect enemy movement and age before deciding where to go.",
  ".enemy",
);
place(
  "ward-place",
  "ward",
  16,
  "Place Ward in the marked space nearer to you. It starts with 0 block and cannot defend until activated. Isolated means it needs empty neighboring spaces to activate.",
);
phase("ward-phase");
activate(
  "ward-activate",
  16,
  "Activate Ward to gain 10 block: it now stores 10. Unlike Shield, that stock will persist across rounds.",
);
end("ward-enemy");
defend("ward-block", "ward", 16, "Choose Ward to absorb the 3-damage attack.");
note(
  "ward-persists",
  "7 block remains",
  "Ward kept its remaining 7 block into this round. You do not have to activate it every turn. When depleted, it cannot protect you further.",
  '[data-slot="16"]',
);
place(
  "sapling-place",
  "sapling",
  20,
  "Place Sapling on the far-right marked space. Allies have HP, can attack, and may intercept incoming attacks.",
);
phase("sapling-phase");
activate(
  "sapling-attack",
  20,
  "Activate Sapling to attack with its current 4 HP. Your Ring adds 2. It can still defend even though it has attacked this turn.",
);
end(
  "rootling-rest",
  "Rootling spends this move Gathering Strength. Advance and use the breathing room to prepare your defense.",
);
place(
  "route-shield",
  "shield",
  18,
  "Place Shield between Sapling on the right and Ward on the left. This is the route the next attack will take.",
);
phase("route-phase");
activate(
  "route-shield-activate",
  18,
  "Activate Shield to create 4 block between your Ally and Ward.",
);
activate(
  "route-sapling-attack",
  20,
  "Use Sapling’s second attack. It spends its final attack allowance, but its remaining HP can still intercept damage.",
);
note(
  "route",
  "Block from right to left",
  "Rootling is winding up a 30-damage attack. Choose Sapling, then Shield, then Ward, then Bracelet. Once the attack passes a column, cards farther right cannot defend it. In normal play you may skip a defense or click your Druid to take the hit.",
  '.enemy .tell, [data-slot="20"], [data-slot="18"], [data-slot="16"]',
);
end("route-enemy");
defend(
  "route-ally",
  "intercept",
  20,
  "Click Sapling. Its 4 HP absorb 4 damage. It dies and enters Destroyed until the next battle. Watch the remaining 26 damage stop here.",
);
defend(
  "route-block",
  "block",
  18,
  "Click Shield. Its 4 block stop 4 more damage. The remaining 22 continue leftward.",
);
defend(
  "route-ward",
  "ward",
  16,
  "Click Ward. Its stored 7 block absorb 7, leaving 15 damage.",
);
defend(
  "route-bracelet",
  "bracelet",
  null,
  "Click your Bracelet. It stops 2, then the final 13 automatically reach the Druid because no defenses remain.",
);
note(
  "route-done",
  "Every layer matters",
  "You took 13 of the original 30 damage. Each hit showed the actual HP or block lost. The attack never moved backward toward the enemy.",
  ".battle-player, header .hp",
);
place(
  "rootling-blast",
  "blast",
  22,
  "Place Blast on the marked space to finish the weakened Rootling.",
);
phase("rootling-phase");
activate(
  "rootling-kill",
  22,
  "Blast and your Ring deal the remaining 6 damage. Destroyed Allies will be available again next battle.",
);
reward(
  "water-reward",
  "water",
  "Take Water Blast. It will help with the upcoming lesson about elements.",
);
back("rootling-back");
note(
  "gem-road",
  "Return to the item",
  "The way is clear. Continue northeast toward the item you saw before the chase.",
  ".field",
  "gem-road",
);
move("gem-step", 10, 3, "Move northeast, one step closer to the item.");
move("gem-move", 10, 2, "Move north onto the item.");
action(
  "gem-take",
  "A Sapphire",
  "Take the Sapphire. Gems imbue Settings such as Bracelets and Rings; they are not worn by themselves.",
  { type: "takeItem", index: 0 },
);
note(
  "gem-save",
  "Save it for the Tavern",
  "You may equip ordinary items during map movement, but Gems may be socketed or removed only at a Tavern. We will save this Sapphire for your Bracelet.",
  '[data-ui="inventory"]',
);
note(
  "curses",
  "Read before you take",
  "Some objects are Cursed; some cards are Hexes. Their drawbacks can persist between battles. Inspect their text before taking them. A visiting Tavern Healer can remove them, sometimes for Gold, HP or a sacrifice.",
  '[data-ui="grimoire"], [data-ui="inventory"]',
  "ember",
);
move(
  "ember-move",
  9,
  2,
  "Move west onto the Ember Mote to explore elemental matchups.",
);
note(
  "elements",
  "Fire meets Water",
  "This enemy is Fire. Water attacks deal +50% damage to Fire, rounded up; Earth attacks deal half. Arcane stays neutral. The enemy’s Tell also shows the element of its attack.",
  ".enemy",
);
place("water-place", "water", 22, "Place Water Blast on the marked space.");
phase("water-phase");
activate(
  "water-attack",
  22,
  "Water Blast’s 7 becomes 11 against Fire. Your unsocketed Ring adds a neutral 2. Drag over the enemy to see the elemental preview.",
);
end("ember-enemy");
defend(
  "ember-bracelet",
  "bracelet",
  null,
  "Your unsocketed Bracelet blocks 2 of the 3 Fire damage; the last 1 reaches you. A Fire-imbued defense is strongest against Fire. Water defense is strongest against Water, even though Water attacks beat Fire.",
);
place(
  "attune-place",
  "blast",
  23,
  "Place Blast beside Water Blast. An adjacent elemental card gives Blast an Attunement choice.",
);
phase("attune-phase");
activate(
  "attune-attack",
  23,
  "Activate Blast as Water against the Fire enemy. Its 4 becomes 6; your Ring supplies the final 2.",
  "Water",
);
action(
  "element-back",
  "Back to the path",
  "Return to the Field after seeing the enemy defeated.",
  { type: "continueReward" },
);
note(
  "cycle",
  "Remember the cycle",
  "Fire burns Earth. Earth blocks Wind. Wind dries Water. Water douses Fire. Chaos swallows Light; Light overwhelms Chaos. The verbs describe attack advantage. Both Chaos and Light are strong against each other.",
  ".field",
  "tavern",
);
move(
  "tavern-move",
  8,
  2,
  "Move west into the Lantern Rest. You have enough Gold for every lesson.",
);
ui(
  "scribe",
  "Visit the Scribe",
  "Click the Scribe in the Tavern. Upgrades strengthen a specific card, and their costs are shown before purchase.",
  "tavern:grimoire",
  '[data-tavern="grimoire"]',
);
action(
  "upgrade",
  "Upgrade Blast",
  "Choose the highlighted Blast upgrade. Its printed damage rises from 4 to 7.",
  { type: "upgrade", card: "blast" },
);
ui(
  "market",
  "Visit the Market",
  "Click the Market. You can View an item before you Buy it.",
  "tavern:market",
  '[data-tavern="market"]',
);
ui(
  "market-equipment",
  "Choose Equipment",
  "Open the Equipment tab to see the helmet for sale.",
  "market:Equipment",
  '[data-market-category="Equipment"]',
);
action(
  "helmet-buy",
  "Buy the helmet",
  "Buy the Sturdy Metal Helmet for 75 Gold. It adds +2 to the block produced by your Shields.",
  { type: "buy", itemId: "crown" },
);
ui(
  "jeweler",
  "Visit the Jeweler",
  "Click the Jeweler for your equipment and Gem sockets.",
  "tavern:equipment",
  '[data-tavern="equipment"]',
);
action(
  "helmet-equip",
  "Wear the helmet",
  "Drag the helmet into your head slot, or inspect it and choose Equip.",
  { type: "equip", itemId: "crown", slot: "head" },
  '.satchel, [data-equip-slot="head"]',
);
action(
  "socket",
  "Imbue the Bracelet",
  "Drag the Sapphire into the Bracelet’s Gem socket, or inspect the Gem and choose the Bracelet. Your Bracelet now has Water defense.",
  { type: "socket", itemId: "bronze", gemId: "sapphire" },
  '.satchel, [data-equip-slot="wrist2"]',
);
ui(
  "traveler",
  "Hear the rumors",
  "Click the Traveler to hear gossip about the Archon.",
  "tavern:gossip",
  '[data-tavern="gossip"]',
);
action(
  "gossip",
  "Learn what lies ahead",
  "Pay 15 Gold for gossip. It reveals Cinder Hart, the Archon of this lesson’s imagined onward journey. You will not fight that boss in the tutorial.",
  { type: "gossip" },
);
ui(
  "innkeeper",
  "Rest at the inn",
  "Click the Innkeeper. The earlier damage gives you a reason to recover.",
  "tavern:rest",
  '[data-tavern="rest"]',
);
action("rest", "Recover HP", "Spend 20 Gold to recover up to 20 HP.", {
  type: "heal",
});
ui(
  "healer",
  "Meet the Healer",
  "Click the Healer. This visitor treats Hexes and Cursed equipment, separately from ordinary paid card removal.",
  "tavern:healer",
  '[data-tavern="healer"]',
);
note(
  "healer-help",
  "A different price for every affliction",
  "You have no Hexes or Curses to remove. In a normal journey, read the treatment: it may require Gold, HP, an Ally or an item. Ordinary card removal is limited to one per Tavern; Hex treatment is separate.",
  ".tavern-service",
);
action(
  "leave-tavern",
  "One final challenge",
  "Leave the Tavern. Your final encounter is a gentle Eidolon, the Patient Warden.",
  { type: "leave" },
);
note(
  "final-intro",
  "The Patient Warden",
  "You are on your own for this fight. Inspect its Tell, place your cards, watch your resources, and choose how to defend. It alternates pauses with modest attacks. Optional tooltips remain available.",
  ".field",
  "final",
);
move(
  "final-move",
  7,
  2,
  "Move west to challenge the Patient Warden. Defeating it completes The First Clearing.",
);
steps.push({
  id: "independent",
  kind: "free",
  title: "Your turn to decide",
  text: "Use what you have learned. Read the Tell, spend Focus and Channel, and defend from right to left. Defeat the Patient Warden to finish the tutorial.",
  focus: "",
});
export const TUTORIAL_STEPS = steps;
export function tutorialGuide(g) {
  const t = g.s.tutorial;
  return t && !t.completed
    ? {
        ...steps[t.step],
        index: t.step,
        total: steps.length,
        name: TUTORIAL.name,
      }
    : null;
}
const item = (g, id) => g.s.inventory.find((x) => x.id === id);
function matches(g, a, m) {
  return Object.entries(m).every(([k, v]) => {
    if (k === "card")
      return (
        (
          g.s.battle?.hand.find((c) => c.uid === a.uid) ||
          g.s.deck.find((c) => c.uid === a.uid)
        )?.id === v
      );
    if (k === "itemId")
      return a.type === "buy"
        ? g.s.shop.stock[a.index] === v
        : item(g, v)?.uid === (a.item ?? a.uid);
    if (k === "gemId") return item(g, v)?.uid === a.gem;
    return a[k] === v;
  });
}
export function tutorialActions(g, raw) {
  const t = g.s.tutorial,
    step = steps[t?.step];
  if (!t) return raw;
  if (g.s.mode === "result")
    return g.s.outcome === "loss" && t.finalStart
      ? [
          {
            type: "tutorialRetry",
            label: "Retry the Warden",
            key: '["tutorialRetry"]',
            effects: { progress: 1 },
            costs: {},
          },
        ]
      : [];
  if (step.kind === "free") return raw;
  if (step.kind === "action")
    return raw
      .filter((a) => matches(g, a, step.match))
      .slice(
        0,
        step.match.type === "place" || step.match.type === "upgrade"
          ? 1
          : undefined,
      );
  const type = step.kind === "ui" ? "tutorialUI" : "tutorialNext";
  return [
    {
      type,
      step: step.id,
      control: step.control,
      label: step.kind === "ui" ? step.title : "Continue lesson",
      key: JSON.stringify([type, { step: step.id }]),
      effects: { progress: 1 },
      costs: {},
    },
  ];
}
function spawn(g, type, x, y, extra = {}) {
  g.s.field.entities.push({
    uid: g.uid(),
    type,
    x,
    y,
    born: g.s.field.round,
    restless: 0,
    ...extra,
  });
}
function enter(g) {
  const t = g.s.tutorial,
    step = steps[t.step],
    f = g.s.field;
  if (!step) throw Error("Unknown tutorial step");
  t.lesson = step.id;
  switch (step.setup) {
    case "gold":
      spawn(g, "Gold", 6, 5, { value: 200 });
      break;
    case "ring":
      spawn(g, "Item", 7, 5, { item: "ring" });
      break;
    case "mote":
      spawn(g, "Mote", 8, 5, { enemy: "tutorialMosswing", count: 1 });
      break;
    case "pursuit":
      spawn(g, "Item", 10, 2, { item: "sapphire" });
      spawn(g, "Mote", 8, 6, { enemy: "tutorialRootling", count: 1 });
      f.moves = 1;
      break;
    case "gem-road":
      f.moves = 2;
      break;
    case "ember":
      spawn(g, "Mote", 9, 2, { enemy: "tutorialEmber", count: 1 });
      break;
    case "tavern":
      spawn(g, "Tavern", 8, 2);
      break;
    case "final":
      spawn(g, "Eidolon", 7, 2, { enemy: "tutorialWarden", count: 1 });
      break;
  }
}
export function startTutorial(g) {
  const s = g.s;
  s.tutorial = {
    ...TUTORIAL,
    step: 0,
    lesson: "welcome",
    fight: 0,
    completed: false,
  };
  s.mode = "field";
  s.archon = "hart";
  s.revealedArchon = null;
  s.gold = 0;
  s.inventory = s.inventory.filter((x) => x.id === "bronze");
  for (const k of Object.keys(s.equipment))
    if (k !== "wrist2") s.equipment[k] = null;
  s.deck = [
    ...Array(4).fill("shield"),
    ...Array(4).fill("blast"),
    "sapling",
    "clear",
  ].map((id) => g.newCard(id));
  Object.assign(s.field, {
    round: 1,
    spawned: 0,
    queue: [],
    entities: [],
    x: 5,
    y: 5,
    moves: 2,
    stage: "player",
  });
  s.stats.itemsGained = ["Bronze Bracelet"];
  enter(g);
  return g;
}
export function tutorialAfter(g, a) {
  const t = g.s.tutorial;
  if (!t) return;
  if (a.type === "tutorialRetry") {
    const saved = t.finalStart;
    g.s.battle = structuredClone(saved.battle);
    g.s.hp = saved.hp;
    g.s.status = { burn: 0, poison: 0, corrode: 0 };
    g.s.mode = "battle";
    delete g.s.outcome;
    delete g.s.death;
    delete g.s.cause;
    g.s.stats.encounters.push({
      round: g.s.field.round,
      enemies: [enemies.tutorialWarden.name],
      outcome: "in progress",
      hpStart: g.s.hp,
    });
    t.completed = false;
    t.step = steps.length - 1;
    t.lesson = "independent";
    t.retries = (t.retries || 0) + 1;
    return;
  }
  if (steps[t.step].kind === "free" || t.completed) return;
  t.step++;
  enter(g);
}
export function tutorialBattle(g, entities) {
  if (!g.s.tutorial) return;
  g.s.tutorial.fight =
    {
      tutorialMosswing: 1,
      tutorialRootling: 2,
      tutorialEmber: 3,
      tutorialWarden: 4,
    }[entities[0].enemy] || 0;
}
export function tutorialBattleReady(g) {
  const t = g.s.tutorial;
  if (t?.fight === 4)
    t.finalStart = { battle: structuredClone(g.s.battle), hp: g.s.hp };
}
export function tutorialDrawIndex(g, n) {
  const b = g.s.battle,
    t = g.s.tutorial;
  const plans = {
    1: {
      1: ["shield", "shield", "shield", "shield"],
      2: ["blast", "blast", "blast", "blast"],
      3: ["sapling", "clear", "blast", "blast"],
    },
    2: {
      1: ["ward", "blast", "blast", "clear"],
      2: ["sapling", "blast", "blast", "shield"],
      3: ["shield", "shield", "shield", "blast"],
      4: ["blast"],
    },
    3: { 1: ["water", "shield", "shield", "shield"], 2: ["blast"] },
  };
  const id = plans[t.fight]?.[b.turn]?.[n];
  const i = b.deck.findIndex((c) => c.id === id);
  return i < 0 ? 0 : i;
}
export function tutorialReward(g) {
  const t = g.s.tutorial;
  if (!t) return false;
  if (t.fight === 4) {
    t.completed = true;
    g.finish(true, "The First Clearing complete");
    return true;
  }
  g.s.reward = {
    cards: t.fight === 1 ? ["ward"] : t.fight === 2 ? ["water"] : null,
    gem: false,
    setting: false,
    boss: false,
  };
  return false;
}
export function tutorialTavern(g) {
  if (!g.s.tutorial) return;
  g.s.shop = {
    stock: ["crown"],
    healer: true,
    healerPrice: 35,
    hexPrice: { kind: "gold", gold: 35, hp: 0 },
    healUsed: false,
    removeUsed: false,
  };
}

sources.policy.mjs:
import { cards, items, enemies, VERSION } from "./content.mjs";
import {
  offense,
  defenseRate,
  adjacent,
  allyHit,
  corner,
  enemyStatusImmunity,
} from "./engine.mjs";
export const defaultWeights = {
  damage: 1,
  survival: 1.4,
  economy: 4,
  development: 1,
  progress: 1,
};
const dist = (a, b) => Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
export class WeightedPolicy {
  constructor(weights = {}) {
    this.weights = { ...defaultWeights, ...weights };
    this.id = "weighted-druid-v1.12";
  }
  choose(o, actions) {
    if (!actions.length) return null;
    let winner = actions[0],
      best = -Infinity,
      reason = "Use an available legal choice.";
    for (const a of actions) {
      let score = -0.01,
        why = "Fallback for a legal choice with unfamiliar effects.";
      try {
        [score, why] = this.score(o, a);
        if (!Number.isFinite(score)) score = -0.01;
      } catch {}
      if (score > best) {
        best = score;
        winner = a;
        reason = why;
      }
    }
    return { action: winner, reason, score: best, policy: this.id };
  }
  cardValue(id, o) {
    const d = cards[id];
    if (!d) return 0;
    const e = d.effects;
    return (
      (e.damage || 0) / (d.charge || 1) +
      (d.hp || 0) * 0.6 +
      (e.ward || 0) * 0.55 +
      (e.shield || 0) * 0.4 +
      (e.channel || 0) * 6 +
      (e.focusPermanent || 0) * 10 +
      (e.heal || 0) * 1.5 +
      (e.poison || 0) * 3 +
      (e.burn || 0) * 2 +
      (e.corrode || 0) * 6 +
      (e.hpDamage ? 8 : 0) +
      (d.growth ? 8 : 0) -
      (d.focus - 1) * 3 -
      (d.type === "Hex" ? 40 : 0)
    );
  }
  gearValue(e = {}) {
    return (
      (e.channel || 0) * 20 +
      (e.focus || 0) * 14 +
      (e.insight || 0) * 6 +
      (e.block || 0) * 2 +
      (e.heal || 0) * 6 +
      (e.armor || 0) * 6 +
      (e.damage || 0) * 3 +
      (e.movement || 0) * 3 +
      (e.resist ? 4 : 0)
    );
  }
  score(o, a) {
    const f = a.effects || {},
      w = this.weights,
      b = o.battle,
      injured = o.maxHp - o.hp;
    let n = 0,
      reason = a.label;
    switch (a.type) {
      case "chooseClass":
      case "begin":
      case "continueReward":
        return [10, "Advance the journey."];
      case "startGem":
        return [
          f.defense ? 10 : 4,
          "Imbue the starting Bracelet for passive protection.",
        ];
      case "unequip":
        return [
          -25,
          "Keep equipped gear unless replacing it with better gear.",
        ];
      case "equip": {
        const inst = o.inventory.find((x) => x.uid === a.item),
          old = o.inventory.find((x) => x.uid === o.equipment[a.slot]);
        n =
          this.gearValue(items[inst.id].effect) -
          this.gearValue(items[old?.id]?.effect) -
          (Object.values(o.equipment).includes(inst.uid)
            ? this.gearValue(items[inst.id].effect)
            : 0);
        return [
          n > 0 ? 30 + n : -20,
          "Equip gear only when its evaluated benefit improves this slot.",
        ];
      }
      case "move": {
        const p = { x: a.x, y: a.y };
        const targets = o.field.entities.map((e) => {
          let value =
            e.type === "Gold"
              ? e.value * 0.35
              : e.type === "Item"
                ? 25
                : e.type === "Event"
                  ? 20
                  : e.type === "Tavern"
                    ? o.gold >= 20
                      ? injured * 0.8 + 12
                      : 2
                    : e.enemy
                      ? enemies[e.enemy].tier === "Archon"
                        ? o.field.round > 18
                          ? 20
                          : -5
                        : enemies[e.enemy].tier === "Eidolon"
                          ? -12
                          : 9
                      : 0;
          if (e.enemy) value -= ((e.count || 1) - 1) * 5;
          const d = dist(p, e),
            old = dist(o.field, e);
          return { e, score: value / (d + 1) + (old - d) * 3 };
        });
        n = targets.length ? Math.max(...targets.map((x) => x.score)) : 0;
        for (const e of o.field.entities.filter((x) => x.enemy)) {
          if (dist(p, e) === 0) {
            n -= ((e.count || 1) - 1) * (o.hp < 30 ? 8 : 3);
            const tier = enemies[e.enemy].tier;
            n -=
              tier === "Eidolon"
                ? 12
                : tier === "Archon" && o.field.round < 18
                  ? 8
                  : 0;
          }
          if (o.hp < 20 && dist(p, e) <= 2) n -= 3;
        }
        n -= dist(p, { x: 5, y: 5 }) * 0.1;
        return [
          n,
          "Move toward useful visible encounters, favoring recovery and avoiding dangerous packs.",
        ];
      }
      case "wait":
        return [-1, "End movement when there is no better destination."];
      case "place": {
        const c = cards[f.card],
          e = c.effects,
          slot = b.grid[a.slot],
          ns = adjacent(a.slot).filter((i) => b.grid[i].length),
          existing = b.grid.flat().filter((x) => x.id === c.id).length;
        const hasOffense = b.grid.some((x) => {
          const t = x.at(-1);
          return (
            t &&
            t.used < cards[t.id].limit &&
            (cards[t.id].effects.damage || cards[t.id].effects.hpDamage)
          );
        });
        n = this.cardValue(c.id, o) * 0.5 + 2;
        if (e.focusPermanent) n += b.turn < 5 ? 12 : 2;
        if (c.growth) n += 8 + ns.length * 3;
        if (e.damage && !hasOffense) n += 8;
        if (e.shield && existing) n -= 12;
        if (c.condition === "isolated") n += ns.length ? -30 : 4;
        if (c.condition === "corner" && !corner(a.slot)) n -= 30;
        if (
          c.condition &&
          ["Earth", "Fire", "Wind", "Water"].includes(c.condition) &&
          !ns.some((i) => b.grid[i].at(-1).element === c.condition)
        )
          n -= 20;
        if (e.adj) n += ns.length * 2;
        if (e.matchingDamage || e.matchingShield)
          n +=
            ns.filter(
              (i) => b.grid[i].at(-1).id === c.id && !b.grid[i].at(-1).sever,
            ).length * 2;
        if (c.attune)
          n += ns.some((i) => b.grid[i].at(-1).element !== "Arcane") ? 1 : 0;
        for (const i of ns) if (cards[b.grid[i].at(-1).id].growth) n += 3;
        if (slot.length && !c.stack) n -= 50;
        if (
          c.stack === "supersede" &&
          slot.at(-1)?.used < cards[slot.at(-1).id].limit
        )
          n -= 10;
        if (c.stack === "tower" && !slot.length) n -= 6;
        return [
          n * w.development,
          "Develop usable offense, growth, and economy while preserving placement conditions.",
        ];
      }
      case "recall":
        return [
          f.spent && b.grid.filter((x) => x.length).length > 10 ? 3 : -15,
          "Clear exhausted cards only when grid space is scarce.",
        ];
      case "activatePhase":
      case "endTurn":
        return [-1, "Advance after worthwhile actions are used."];
      case "activate": {
        const target = b.enemies.find((e) => e.uid === a.target);
        const threat = b.enemies.reduce(
          (sum, e) => sum + (e.tell.damage || 0) * (e.tell.hits || 1),
          0,
        );
        const protectedBy =
          b.grid.flat().reduce((sum, c) => sum + (c.ward || 0), 0) +
          b.shields.reduce((sum, p) => sum + p.block, 0) +
          o.bonuses.armor +
          3;
        let damage =
          f.damage || f.chargedDamage || (f.randomDamage && 6.5) || 0;
        if (f.charge > 1) damage /= f.charge;
        if (target) {
          damage = offense(damage, a.element, target.element);
          if (target.resist === a.element) damage = Math.ceil(damage / 2);
          if (target.wisp) damage *= a.element === "Arcane" ? 0.5 : 2;
          if (target.flicker) damage = 0.5;
          if (damage >= target.hp) n += 15;
          damage = Math.min(damage, target.hp);
          if (target.id === "colossus" && a.element === "Chaos") n -= 8;
        }
        if (f.all) damage *= b.enemies.length;
        n +=
          damage * w.damage +
          (target && enemyStatusImmunity(target) === "burn"
            ? 0
            : (f.burn || 0) * 2) +
          (f.burnAll || (f.chargedBurnAll || 0) / (f.charge || 1)) *
            b.enemies.filter((e) => enemyStatusImmunity(e) !== "burn").length *
            2 +
          (target && enemyStatusImmunity(target) === "poison"
            ? 0
            : (f.poison || 0) * 3) +
          (target && enemyStatusImmunity(target) === "corrode"
            ? 0
            : (f.corrode || 0) * 5);
        n += (f.channel || 0) > a.costs.channel ? 12 : 0;
        n += (f.focusPermanent || 0) * (b.turn < 7 ? 12 : 4);
        n += (f.insight || 0) * 0.4 + (f.focus || 0) * 1.2;
        n += Math.min(injured, f.heal || 0) * w.survival;
        if (f.cleanse)
          n += Object.values(o.status).reduce((x, y) => x + y, 0) * 2;
        if (f.shield)
          n +=
            Math.min(f.shield, Math.max(0, threat - protectedBy)) * w.survival;
        if (f.ward)
          n += Math.min(f.ward, Math.max(0, threat + 3 - protectedBy));
        if (f.taunt) n += o.hp < 15 ? 6 : 0;
        if (f.relief) n += b.turn > b.relief ? 5 : -10;
        if (f.unbind)
          n +=
            b.grid.flat().filter((x) => x.lock || x.sever || x.freeze).length *
            4;
        if (f.allyHeal) n += 4;
        if (f.magnify) n += 3;
        if (f.shift || f.transmute) n -= 4;
        return [
          n,
          "Balance immediate kills, incoming damage, healing, and future resources.",
        ];
      }
      case "ward":
        return [
          Math.min(f.ward, b.reaction.damage) * w.survival + (f.column + 1) * 2,
          "Absorb damage while preserving defenders closer to the player.",
        ];
      case "block":
      case "bracelet":
        return [
          Math.min(
            b.reaction.damage,
            f.block * defenseRate(f.element, b.reaction.element),
          ) *
            w.survival +
            ((f.column ?? -1) + 1) * 2,
          "Use the portion with the strongest effective block against this element.",
        ];
      case "intercept": {
        const c = b.grid[a.slot].at(-1),
          d = cards[c.id],
          result = allyHit(b.reaction, c.element, c.hp, f.swallow);
        return [
          (b.reaction.damage - result.remaining) * w.survival -
            (d.growth ? 8 : 0) -
            (d.effects.heal ? 5 : 0) +
            (f.swallow ? b.reaction.damage : 0) +
            ((f.column ?? 0) + 1) * 2,
          "Protect player HP while retaining valuable growing Allies when possible.",
        ];
      }
      case "skipEquipment":
        return [
          -Math.max(0, b.reaction.damage - o.bonuses.armor) * w.survival,
          "Preserve item block by accepting the remaining hit; prefer blocking damage when possible.",
        ];
      case "takeHit":
        return [
          b.bracelets.reduce((n, p) => n + p.block, 0) +
            o.bonuses.armor -
            (o.hp < 20 ? 10 : 0),
          "Let passive equipment absorb a manageable hit.",
        ];
      case "rewardCard":
        return [
          this.cardValue(a.id, o) - (o.deck.length > 20 ? 6 : 0),
          "Choose a card by its damage, defense, economy, and growth features.",
        ];
      case "leaveItem":
        return [0, "Leave an unwanted item without accepting its effects."];
      case "skipReward":
        return [0, "Skip a card that would dilute the deck."];
      case "rewardGem":
      case "rewardSetting":
        return [
          this.gearValue(f.gear),
          "Prefer permanent economy and passive protection.",
        ];
      case "takeItem":
      case "buy": {
        const id = f.item,
          d = id?.startsWith("card:") ? null : items[id];
        n = d
          ? this.gearValue(d.effect) +
            (d.slot === "gem" ? 3 : 0) -
            (d.cursed ? 40 : 0)
          : this.cardValue(id?.slice(5), o);
        if (a.type === "buy") n -= a.price * 0.13;
        return [n, "Value the offered item against its price and risk."];
      }
      case "heal":
        return [injured * 0.9, "Recover HP before the next encounter."];
      case "eventChoice":
        return [
          (f.heal ? Math.min(injured, f.heal) * 1.4 : 0) +
            (f.gold || 0) * 0.2 +
            (f.hp || 0) * 1.5 +
            (f.card ? this.cardValue(f.card, o) : 0) +
            (f.hex ? -30 : 0) +
            (f.item
              ? this.gearValue(items[f.item].effect) -
                (items[f.item].cursed ? 25 : 0)
              : 0) +
            (f.clean || f.cleanHex
              ? o.deck.filter((x) => cards[x.id].type === "Hex").length * 20
              : 0) -
            (a.costs.gold || 0) * 0.2 -
            (a.tradeItem != null
              ? this.gearValue(
                  items[o.inventory.find((x) => x.uid === a.tradeItem).id]
                    .effect,
                )
              : 0) -
            (a.tradeCard != null
              ? this.cardValue(o.deck.find((x) => x.uid === a.tradeCard).id, o)
              : 0),
          "Compare the visible reward with the cost of the specific offered item or card.",
        ];
      case "socket": {
        const inst = o.inventory.find((x) => x.uid === a.uid),
          old = o.inventory.find((x) => x.uid === inst.gem),
          g = o.inventory.find((x) => x.uid === a.gem);
        return [
          this.gearValue(items[g.id].effect) -
            this.gearValue(items[old?.id]?.effect) +
            (old ? -10 : 10),
          "Socket unused Gems to activate their powers.",
        ];
      }
      case "upgrade":
        return [
          8 - (a.costs.gold || 0) * 0.06 - (a.costs.hp || 0) * 0.7,
          "Improve a card when the cost is affordable.",
        ];
      case "removeHex": {
        const lostCard = o.deck.find((c) => c.uid === a.sacrificeCard);
        const lostItem = o.inventory.find((x) => x.uid === a.sacrificeItem);
        const hpCost = a.costs.hp || 0;
        return [
          25 -
            hpCost * (o.hp < 25 ? 2 : 0.8) -
            (a.costs.gold || 0) * 0.06 -
            (lostCard ? this.cardValue(lostCard.id, o) : 0) -
            (lostItem ? this.gearValue(items[lostItem.id].effect) : 0),
          "Weigh Hex relief against the displayed HP, Gold, or sacrifice cost.",
        ];
      }
      case "sell":
        return [
          f.cursed ? 10 : -30,
          "Keep useful equipment; pay to remove a Curse.",
        ];
      case "gossip":
        return [
          !o.archon && o.gold > 100 ? 2 : -5,
          "Buy Archon information only with surplus Gold.",
        ];
      case "leave":
        return [0, "Continue when useful services are exhausted."];
      case "replaceArmor":
        return [
          this.gearValue(f.gear) -
            this.gearValue(
              items[o.inventory.find((x) => x.uid === a.old).id].effect,
            ),
          "Replace Armor only for a better evaluated effect.",
        ];
      case "declineArmor":
        return [0, "Respect the three-Armor carry limit."];
      case "remove":
      case "unsocket":
        return [-20, "Avoid unnecessary deck removal or socket churn."];
      default:
        return [
          Object.values(f)
            .filter((x) => typeof x === "number")
            .reduce((a, b) => a + b, 0) * 0.01,
          "Fallback: choose a legal action using available public effects.",
        ];
    }
  }
}

